    "id": 82,
    "t": "Codex Security: עכשיו בתצוגה מקדימה למחקר\n\nOpenAI השיקה את Codex Security, סוכן AI חדש שמתמחה באבטחת קוד. הכלי החדש מנתח את ההקשר של הפרויקט שלכם כדי לתפוס באגים ליקויים בטחוניים מורכבים, לאמת אותם ולתקן אותם - וזה עם פחות false alarms מאשר הפתרונות הקיימים. במילים אחרות, הוא מבין טוב יותר את הקוד שלכם ולא יעלה עליכם כל הודעת אזהרה כוזבת.",
