    "t": "איך Balyasny Asset Management בנתה מנוע AI לחקר השקעות\n\nBalyasny לקחה את זה לרמה הבאה - בנתה מערכת חקר AI שלמה עם GPT-5.4 שמנתחת השקעות בקנה מידה ענק. הם שילבו הערכת מודלים קפדנית ו-agent workflows כדי להפוך את ניתוח ההשקעות למהיר, חכם ובקנה מידה שאף אדם לא יכול להשיג. רוצים לדעת איך בדיוק בנו את המערכת הזו? OpenAI Blog",
