    "t": "איך מהנדסי Descript משיגים דובינג וידאו רב-לשוני בקנה מידה ענק\n\nDescript השתמשה בודלי ה-reasoning החדשים של OpenAI כדי להפוך את כל ספריית התוכן שלהם לזמינה בשפות שונות באופן אוטומטי - וללא לאבד את התיזומון או משמעות התוכן. זה בעצם חוק: עכשיו תוכן אחד יכול להיות זמין לעשרות מיליוני צופים ברחבי העולם בשפתם שלהם.",
