    "t": "מודלי reasoning מתקשים לשלוט בשרשרת המחשבות שלהם - וזה למעשה טוב\n\nOpenAI חקרה כיצד מודלים חדשים שעובדים עם reasoning מתקשים לשלוט בתהליך החשיבה שלהם, וגילתה שהדבר יכול למעשה לחזק את הביטחון של AI. התגלית הזו מצביעה על כך שניתן לעקוב אחרי החלטות המודלים בקלות רבה יותר מאשר חשבנו, דבר שיכול להיות בטוח למערכות AI בעתיד. OpenAI מציגה את CoT-Control, כלי חדש שעוזר להבין ולהשגיח על תהליך ההחלטות של מודלים אלו.",
