    "t": "סביבת Runtime מצומדת למסכנים ב-Amazon Bedrock\n\nאמזון הטילה סביבה חדשה ב-Bedrock שמאפשרת למסכנים AI להחזיק זיכרון ולהשתמר בין שלבים - כמו שהסוכן שלכם יכול סוף סוף לזכור מה קרה לו וממשיך בעבודה מעניינת מורכבת. התוכנית מושלמת למשימות רב-שלביות שדורשות תזכורת וביצוע מאובטח, ואפילו משתמשת במודלים של OpenAI.",
