    "t": "מעבדת פציפיק נורת'וסט הלאומית ו-OpenAI שותפות להאצת הליכים פדרליים\n\nOpenAI והמעבדה הלאומית בפציפיק נורט'וסט הציגו את DraftNEPABench - benchmark חדש שמעריך איך agents של AI יכולים לזרז תהליכים בירוקרטיים פדרליים. התוצאות מראות פוטנציאל לקצר את זמן הכתיבה של דוחות NEPA בעד 15% ולחדש את בדיקות התשתיות בכל הארץ. זה כמו ליתן ניידות של AI למנהלה הממשלתית כדי שתעבוד פי כמה יותר מהר. | מקור: OpenAI Blog",
