    "t": "קידום מחקר עצמאי על יישור AI\n\nOpenAI השקיעה 7.5 מיליון דולר ב-The Alignment Project כדי לתמוך במחקר עצמאי על יישור AI, במטרה לחזק את המאמצים הגלובליים להתמודדות עם סיכוני הבטיחות וההשלטה של AGI. זה בעצם צעד משמעותי של OpenAI לתמוך בקהילית המחקר החיצונית בשביל לוודא שפיתוח AI בטוח ובר-שליטה. מעבר לזה, זה מסמל שהחברה לוקחת ברצינות את הנושא של safety בהקשר של מערכות בינה מלאכותית חזקות בעתיד. מקור: OpenAI Blog",
