    "t": "ServiceNow מחזקת AI ענייני עם מודלים של OpenAI\n\nServiceNow פתחה גישה למודלי ה-frontier של OpenAI בשביל להנעיץ וקופצאות עבודה מונעות AI, סיכום מסמכים, חיפוש ותכונות voice בפלטפורמה שלה. זה בעצם אומר שחברות שמשתמשות ב-ServiceNow יוכלו להשתמש בטכנולוגיית ה-AI המשוכללת של OpenAI ישירות כדי לזרז תהליכים ולהפוך תיבות עבודה מסורתיות למתקדמות ויעילות הרבה יותר.",
