    "t": "השקעה ב-Merge Labs\n\nOpenAI משקיעה ב-Merge Labs, סטארטאפ שפיתח ממשקי מוח-מחשב מהפכניים המחברים בין אינטליגנציה ביולוגית לאינטליגנציה מלאכותית. המטרה היא לשפר את יכולות האדם, העצמאות שלו והחוויה שלו בעולם הדיגיטלי באופן שלא ראינו מעולם. זה בדיוק סוג ה-sci-fi שחושבים שנשמע קצת משוגע, אבל OpenAI לא משחקת איתו. מקור: OpenAI Blog",
