    "t": "OpenAI ו-SoftBank Group משתפות פעולה עם SB Energy לבניית מרכזי נתונים ענקיים למודלי AI\n\nOpenAI ו-SoftBank Group הכריזו על שותפות חדשה עם SB Energy לפיתוח קמפוסי data centers ענקיים בהספק מולטי-ג'יגוואט, כולל מתקן של 1.2 GW בטקסס שיתמוך בפרויקט Stargate החדש. הזירה הזו תשחק תפקיד קריטי בתמיכה בדרישות החישוביות המטורפות של מודלי AI החדישים הקרובים.",
