    "id": 187,
    "t": "הכירו את GPT-5.2-Codex\n\nOpenAI השיקה את GPT-5.2-Codex, מודל הקוד המתקדם ביותר שלה עד כה, שמסוגל לעבוד עם תהליכי חשיבה ארוכים ולבצע שינויים בקנה מידה גדול בקוד. המודל החדש גם מביא עם עצמו יכולות אבטחה סייבר משופרות שאמורות להגן טוב יותר מפני פרצות וחומרות בקוד.",
