    "id": 188,
    "t": "OpenAI משיקה אקדמיה חדשה לארגוני חדשות\n\nOpenAI השיקה את OpenAI Academy - מרכז למידה שנועד לעזור לחדרי עיתונות להשתמש ב-AI בצורה חכמה ואחראית. הפלטפורמה מציעה הדרכות, מקרי שימוש מעשיים וכיווני עבודה שיסייעו לעיתונאים ועורכים להטמיע AI בדיווחיהם ובניהול המערכת שלהם. זה צעד חשוב בעידן שבו עיתונות מחפשת דרכים להשתמש בטכנולוגיה ללא לשלול את האנושיות של התכן. מקור: OpenAI Blog",
