    "t": "מפתחים יכולים כעת להגיש אפליקציות ל-ChatGPT\n\nOpenAI פתחה את הדלת לכל מפתח שרוצה להביא את האפליקציה שלו לתוך ChatGPT - עכשיו אתם יכולים להגיש את היצירה שלכם לבדיקה ואם תאושר, היא תופיע בספריה החדשה והמזמינה בתוך ChatGPT. OpenAI מזינה למפתחים כלים חדשים, Apps SDK מתוחזק, וקווים מנחים שיעזרו לכם לבנות חוויות שמחברות אותנו לעולם האמיתי - כל זה דרך ChatGPT.",
