    "t": "בחינת יכולת ה-AI לביצוע משימות מחקר מדעי\n\nOpenAI הציגה את FrontierScience, בנצ'מארק חדש שבוחן את כושר ההנמקה של מודלי AI בפיזיקה, כימיה וביולוגיה. המטרה? למדוד עד כמה קרובים אנחנו ליום שבו AI יוכל באמת להשתתף במחקר מדעי רציני ולא רק לענות על שאלות. זה בעצם קפיצה משמעותית בהבנת אם המודלים שלנו מסוגלים לחשוב באופן מדעי כמו חוקרים אמיתיים.",
