    "t": "ChatGPT Images החדשה כבר כאן\n\nOpenAI השקה את הגרסה המשודרגת של ChatGPT Images, שמבוססת על מודל ה-image generation הדגלי שלהם. המודל החדש מציע עריכות דקויקות יותר, פרטים עקביים יותר, וייצור תמונות שמהיר פי 4 מהגרסה הקודמת. ההשדרוג מגיע לכל משתמשי ChatGPT היום והוא זמין גם ב-API תחת השם GPT-Image-1.5.\nמקור: OpenAI Blog",
