    "t": "הרחבת אפשרויות שמירת נתונים ללקוחות עסקיים בעולם\n\nOpenAI משיקה תכונת data residency חדשה ל-ChatGPT Enterprise, ChatGPT Edu וה-API Platform, שמאפשרת ללקוחות זכאים לאחסן את הנתונים שלהם בשרתים במקום גיאוגרפי קרוב. זה בעצם מענה לדרישות Compliance וחוקים מקומיים של חברות גדולות שלא רוצות שהנתונים שלהם יטוסו למקום אקראי. פתרון פרקטי שמטבח את ה-AI לשימוש בתאגידים גדולים ברחבי העולם. - OpenAI Blog",
