    "t": "OpenAI עוזרת ל-1,000 עסקים קטנים לבנות עם AI\n\nOpenAI משתפת פעולה עם DoorDash ו-SCORE כדי לתת לבעלי עסקים בשכונות שלנו גישה אמיתית ל-AI - כולל כלים מעשיים והדרכה ישירה. תוכנית \"Small Business AI Jam\" הזאת יכולה להיות משחק משנה לעסקים קטנים שרוצים להתחרות ולגדול בעידן ה-AI. מקור: OpenAI Blog",
