    "t": "גרסה חינמית של ChatGPT שתוכננה במיוחד למורים\n\nOpenAI השיקה סביבת עבודה מאובטחת בשם ChatGPT for Teachers, שמיועדת למורים בחינוך הציבורי בארה\"ב עם בקרות פרטיות בכיתה וניהול למנהלים. הטוב ביותר - זה לגמרי חינמי לכל המורים המאומתים עד יוני 2027, מה שמעניק לחברה כניסה טובה לשוק החינוך דרך גישה ישירה לעובדי מערכת החינוך.",
