    "t": "הצגת IndQA - בנצ'מארק חדש לבדיקת AI בשפות הודיות\n\nOpenAI השיקה את IndQA, בנצ'מארק חדש שמודד כמה טוב מערכות AI משתמשות בשפות הודיות עם הבנה תרבותית עמוקה. המערכת פותחה עם מומחים מקומיים ובודקת reasoning וידע חוצה 12 שפות ו-10 תחומי ידע שונים, מה שצריך לעזור בהכנת AI למיליארדים של משתמשים בתת-היבשת ההודית.",
