    "t": "AWS ו-OpenAI הכריזו על שותפות אסטרטגית רב-שנתית\n\nOpenAI ו-AWS כרתו ידיים על עסקה ענקית בחצי מיליארד דולר שתימשך שנים רבות - AWS תספק את התשתיות וכוח החישוב שדרוש ל-OpenAI כדי להדביק את דור הדברים המחודשים של ה-AI שלה. זה בעצם אומר שצפו לדברים גדולים ממש - כשגיגנט הענן של אמזון משתתף, זה סימן שמדברים על משהו ממש רציני בעולם ה-AI.",
