    "t": "הרחבת Stargate למישיגן\n\nOpenAI משיקה קמפוס חדש בעוצמה של גיגוואט אחד במישיגן כחלק מהרחבת פרויקט Stargate, שנועד לחזק את תשתיות ה-AI האמריקניות. המיזם הזה לא רק יביא עשרות אלפי מקומות עבודה ויזרום השקעות לאזור המערב התיכון, אלא גם יהיה נקודת ציון חשובה בתחרות הגלובלית על יכולות AI.",
