    "t": "פגשו את Aardvark: מחקר ביטחון מעוצב של OpenAI\n\nOpenAI השיקה את Aardvark, חוקר ביטחון בחוכמה מלאכותית שמסוגל לגלות, לאמת ולתקן באופן אוטונומי חורים בטחוניים בתוכנות בקנה מידה ענק. המערכת כרגע בשלב ביטא סגור, אבל אתם יכולים להירשם כדי להשתתף בבדיקות ראשונות. זה בעצם כמו לתת ל-AI לעבוד עבורכם כחוקר ביטחון עצמאי שלא חוסך מאמץ.",
