    "t": "כך בנינו את OWL - הארכיטקטורה החדשה מאחורי Atlas, הדפדפן המבוסס על ChatGPT שלנו\n\nOpenAI חשפה את OWL, הארכיטקטורה המהפכנית שמניעה את Atlas - דפדפן חדש שמשלב ChatGPT בצורה חכמה. בעזרת הניתוק של Chromium מהקוד הראשי, הם הצליחו להשיג טעינה מהירה, ממשק עשיר וביכולת עבודה אוטונומית שלא ראינו קודם. זה בעצם משנה את כל המשחק של איך אנחנו גולשים באינטרנט - ChatGPT לא רק עוזר, הוא הופך להיות חלק אינטגרלי מהחווית הגלישה עצמה.",
