    "t": "דוח טכני: GPT-OSS-Safeguard - מודלים פתוחים לשמירה על בטיחות תוכן\n\nOpenAI הציגה שני מודלי reasoning חדשים - GPT-OSS-Safeguard 120B ו-20B - שמאומנים להערכת תוכן לפי מדיניות נתונה. המודלים האלה מסוגלים לנמק ולהחליט אם תוכן עומד בעמדות ערך ספציפיות, וזה די מהפכני כי הם open-weight ומשאירים הרבה שליטה בידי המשתמשים. בדוח החדש הם גם בודקים את יכולות הבטיחות של המודלים בהשוואה לגרסאות הבסיס שלהם.",
