    "t": "הכירו את gpt-oss-safeguard\n\nOpenAI השיקה מודלי reasoning בקוד פתוח שמסווגים בעיות בטיחותיות, ואתם יכולים להתאים להם כללים משלכם. זה בעצם כלי לפיתוח AI עם שליטה מלאה על מה שאתם רוצים לאפשר ומה לא. מקור: OpenAI Blog",
