    "t": "קדימה בשינוי ארגוני לחדשנות עסקית\n\nDNP הוציאה לדרך את ChatGPT Enterprise בעשרה מחלקות ליבה וקבלה תוצאות מטורללות: חיפוש פטנטים מהיר 95% יותר, עיבוד בנפח גדול פי 10, אוטומציה של 87% וחזרה שימוש בידע של 70% - הכל תוך שלושה חודשים בלבד. זו הוכחה קונקרטית איך AI יכול להשנות ממש את צורת העבודה של ארגונים גדולים ולחסוך הרבה זמן וכח עבודה.",
