    "id": 268,
    "t": "בנוי להטיב לכולם\n\nOpenAI עוברת עיצוב ממיתי בהון עצמי חדש שמחזק את השלטון המוקד על הערכים שלה - כי הם רוצים שהAI תהיה של כולנו ולא של אחדים. התזוזה הזו מכניסה לתוך הקופה משאבים כבדים שיאפשרו להם להמשיך בפיתוח טכנולוגיה חדשה באופן אחראי, בלי להרות את המיסיון המקורי שלהם. במילים אחרות - מעתה יש להם יותר כסף וחופש להתנהל לפי עקרונות, לא לפי מה שחדשנים אחרים עושים.",
