    "t": "OpenAI קנתה את Software Applications Incorporated, יוצרת Sky\n\nOpenAI השלימה עסקה לרכישת Software Applications Incorporated, החברה שמאחורי Sky - ממשק שפה טבעית חדש ל-Mac שמביא AI ישירות לשולחן העבודה שלכם. עכשיו הם משלבים את יכולות macOS העמוקות של Sky ל-ChatGPT כדי לעשות את ה-AI יותר אינטואיטיבי, הקשרי וממוקד על פעולות בפועל. מקור: OpenAI Blog",
