    "t": "ChatGPT Atlas - הדפדפן החדש של OpenAI עם ChatGPT משולב ישירות בתוכו\n\nOpenAI הכניסה את ChatGPT ישירות לדפדפן החדש שלה, ChatGPT Atlas, שמאפשר לכם לקבל תשובות מיידיות וסיכומים של דפים ישר מהדפדפן בלי צורך לעזוב אותו. הדבר הטוב ביותר? כל זה עם שליטה מלאה על פרטיות המידע שלכם. הדפדפן זמין כעת ל-MacOS ופותח לכולנו תקווה לחוויית גלישה עם AI מובנה שלא תשדה את הנתונים שלנו.",
