    "t": "AgentKit, Evals חדשים, ו-RFT לאגנטים - OpenAI משחררת כלים חדשים\n\nOpenAI בא עם ערכת כלים חדשה שתעזור למפתחים להביא אגנטים AI מפרוטוטיפ ישר לייצור: AgentKit (ערכת פיתוח אגנטים), יכולות evals משופרות, ו-Reinforcement Fine-Tuning שמאפשר לחנוך אגנטים בצורה חכמה יותר. זה בעצם הכול שצריך בשביל להרים סטארטאפ סוכנים בימים אלה.",
