    "t": "סמסונג וSK הצטרפו ליוזמת Stargate של OpenAI לקידום תשתיות AI גלובליות\n\nסמסונג וSK קופצות על הרכבת של Stargate, היוזמה החדשה של OpenAI שמטרתה להקים תשתיות AI ממעמד עולמי. שתי הגיגנטים הקוריאניים יתמקדו בייצור שבבי זיכרון מתקדמים ובבניית data centers מהדור הבא בקוריאה, כדי לעזור ל-OpenAI ולעולם ה-AI להשתדל עם הביקוש הגדל על כוח חישוב. זה עוד צעד חשוב בתחרות התשתיות ה-AI הגלובלית.",
