    "t": "מדידת ביצועי המודלים שלנו במשימות בעולם האמיתי\n\nOpenAI הציגה את GDPval, מערכת הערכה חדשה שמודדת את ביצועי מודלי AI בעבודות אמיתיות שיש להן ערך כלכלי אמתי, על פני 44 מקצועות שונים. זה בעצם דרך חדשה וחכמה לבחון אם ה-AI שלהם באמת יכול לתרום כסף למשק - לא רק לעבור טסטים אקדמיים כמו בשעה 3 בלילה. OpenAI בעצם אומרת: בואו נראה איך המודלים שלנו עובדים כשיש דברים על המשחק שקוראים דולרים.",
