    "id": 313,
    "t": "ChatGPT Pulse - התכונה החדשה שתעדכן אתכם באופן חכם\n\nOpenAI השיקה את ChatGPT Pulse - חדש רעיון מגניב שמגיע לכל Pro users בנייד. הכלי הזה עובד כמו עוזר אישי חכם שלכם - הוא חופר בחדשות והמידע בעצמו כדי להביא לכם עדכונים מותאמים אישית בהתאם לשיחות שלכם, למשוב שלכם, ולאפליקציות המחוברות שלכם כמו הלוח השנתי. בעצם, ChatGPT לא רק מחכה שתשאלו - הוא כבר קם בבוקר ומביא לכם בשורות טריות.",
