    "t": "SchoolAI בונה פלטפורמת AI שמעצימה מורים\n\nSchoolAI משתמשת ב-GPT-4.1, יצירת תמונות ו-TTS כדי להנעיל כלים בטוחים מונחים על ידי מורים, שכבר משמשים למעל מיליון כיתות בעולם. הפלטפורמה עוזרת להגביר את מעורבות התלמידים, לתן למורים שליטה מלאה, ולהציע למידה מותאמת אישית - כל זה עם שמירה על בטיחות במרחב כיתה.",
