    "t": "OpenAI ו-NVIDIA מכריזות על שותפות אסטרטגית לפריסת 10 ג'יגוואט של מערכות NVIDIA\n\nOpenAI ו-NVIDIA התחברו בשותפות ענקית שתביא ל-10 ג'יגוואט של דאטה סנטרים AI מבוססי NVIDIA - זה כמו להשקיע במשהו ענק שיהפוך את עולם ה-AI. השלב הראשון של הפרויקט המטורף הזה יתחיל ב-2026, וזה בעצם אומר שהחברות הללו משקיעות ברצינות בתשתיות שיתמכו בדור הבא של מודלים ולמידה עמוקה.\n\nמקור: OpenAI Blog",
