    "t": "שדרוג חדש לקודקס של OpenAI\n\nקודקס השתפר משמעותית - עכשיו הוא יותר מהיר, יציב יותר, ותומך בשיתוף פעולה בזמן אמת ועבודה עצמאית בכל סביבת פיתוח שאתם משתמשים בה, בין אם זה טרמינל, IDE, דפדפן או אפילו הטלפון שלכם. האپדייט הזה משמעותי עבור מפתחים שרוצים כוח חישובי יותר מהיר ויעיל ישירות מהכלים שהם כבר משתמשים בהם כל יום. מקור: OpenAI Blog",
