    "t": "שיתוף פעולה עם ארגוני AI בארה״ב ובבריטניה לבניית מערכות AI בטוחות יותר\n\nOpenAI מעדכנת על התקדמות בשותפות עם מוסדות בטיחות AI בארה״ב ובבריטניה, שמטרתה להעלות את רמת הביטחון וההגנה של מערכות ה-AI. הקולבורציה הזו היא חלק מהמאמץ הגדול של התעשייה להבין ולהקטין סיכונים בתחום ה-AI לפני שהוא הופך למיינסטרים עוד יותר.",
