    "id": 330,
    "t": "הצהרה על המבנה הלא-רווחי והחברה של OpenAI\n\nOpenAI מחזקת את התפקידה כארגון לא-רווחי עם מבנה חדש שמעניק שוויון בחברה שלה, דבר שמאפשר למעל 100 מיליארד דולר של משאבים להתקדם בכיוון של AI בטוח ומועיל לכל האנושות. התכנית החדשה מייצגת התחייבות ממשית של OpenAI לערכים המקוריים שלה, בעוד שהם צומחים להיות שחקן ענק בתעשיית ה-AI. זה קצת כמו להיות סטארטאפ שלא שכח מאיפה הוא בא. (מקור: OpenAI Blog)",
