    "id": 331,
    "t": "הצהרה משותפת מ-OpenAI ומיקרוסופט\n\nOpenAI ומיקרוסופט חתמו על הסכם שיתוף פעולה חדש שמחזק את הקשר ביניהן בתחום ה-AI והבטיחות של בינה מלאכותית. שתי החברות מתחייבות להמשיך בעבודה משותפת על פיתוח טכנולוגיות AI בטוחות ואחראיות, תוך שמירה על חדשנות וטיקטוק במגזר.",
