    "id": 332,
    "t": "SafetyKit מרחיבה את סוכני הסיכון עם המודלים המתקדמים ביותר של OpenAI\n\nSafetyKit משתמשת ב-GPT-5 של OpenAI כדי להגביר את מודרציית התוכן וזה אומר שבעתיד העיסוק בבטיחות באינטרנט יהיה הרבה יותר חכם ודיוק. המערכת החדשה מתגברת על כל מה שהיה לפני ועובדת הרבה יותר מדויק מ-safety systems הישנים שלנו. בקיצור - זו קפיצת ענק בדרך שאנחנו מוודים את התוכן באינטרנט.",
