    "t": "קרן AI ממוקדת אדם: 50 מיליון דולר לתמיכה בארגונים ללא מטרות רווח\n\nOpenAI פתחה את הרישומים לקרן People-First AI שלה - 50 מיליון דולר שמיועדים לעידוד ארגונים ללא מטרות רווח בארה\"ב בתחומי חינוך, חדשנות קהילתית והזדמנויות כלכליות. זה סיכוי למי שרוצה לעצב את ה-AI למען הטובה הציבורית - אפשר להגיש בקשה עד ה-8 באוקטובר 2025 לגרנטים ללא הגבלות על השימוש.",
