    "id": 335,
    "t": "תוכנית ציד באגים ביולוגיים של GPT-5\n\nOpenAI קוראת לחוקרים להשתתף בתוכנית ציד באגים ביולוגיים חדשה שלהם, שבה תוכלו לבדוק את בטיחות GPT-5 מול jailbreak prompts אוניברסליים ולזכות בעד $25,000. זו הזדמנות סדרית לגיימים ואנשי סייבר לעשות מה שהם הכי אוהבים - לשבור מערכות - רק הפעם זה לשם טוב ובעבור כסף טוב.",
