    "id": 336,
    "t": "OpenAI וממשלת יוון משיקים את 'OpenAI for Greece'\n\nOpenAI וממשלת יוון התחברו בשיתוף פעולה חדש שנקרא 'OpenAI for Greece', שמביא את ChatGPT Edu לבתי ספר תיכוניים ברחבי יוון. התוכנית נועדה להעלות את ההבנה של AI בקרב הדור הצעיר, לתמוך בסטארטאפים מקומיים, וליצור צמיחה כלכלית לאומית - במילים אחרות, יוון הולכת לעשות משהו חכם עם ה-AI 🚀",
