    "t": "ויג'יי ראג'י הופכת ל-CTO של Applications עם רכישת Statsig\n\nויג'יי ראג'י תופסת תפקיד חדש כ-CTO של Applications, תוך שהיא דיווחת ישירות ל-Fidji Simo, מנכ\"ל ה-Applications. זה קורה בעקבות רכישה של Statsig, הפלטפורמה המפורסמת לניהול feature flags וניסויים. המהלך מעידה על החשיבות שמייחסת Meta להנדסת המוצר וה-infrastructure של היישומים שלה.",
