    "t": "בניית חוויות ChatGPT יותר מועילות לכולם\n\nOpenAI מחזקת את ה-ChatGPT שלה עם שיתופי פעולה עם מומחים, הוסיפה בקרות הורים חדשות להגנה על בני נוער, והתחילה לנתב שיחות רגישות לדגמי reasoning מתקדמים. בקיצור - המטרה היא לעשות את ה-AI הזה בטוח וחכם יותר עבור כולנו, במיוחד לנערים וביישנות שלהם.",
