    "id": 340,
    "t": "הכירו את gpt-realtime: מודל הדיבור החדש של OpenAI והעדכונים של ה-API\n\nOpenAI הכריזה על מודל speech-to-speech מתקדם יותר עם יכולות API חדשות שכוללות תמיכה ב-MCP server, קלט תמונות ותמיכה בשיחות טלפון SIP. זה כמעט כמו לתת לـ GPT כוחות טלפוניים אמיתיים עם יכולת להבין ולהשיב בדיבור בזמן אמת.",
