    "t": "תמיכה בחדשנות ללא כוונת רווח וקהילתית\n\nOpenAI הטיפה $50 מיליון דולר לעידוד ארגונים וקהילות - קרן חדשה שנועדה לעזור לארגונים ללא רווח בארה\"ב לגדול בעזרת AI. המבקשים יוכלו להגיש בקשות בין ספטמבר לאוקטובר 2025 לקבלת מלגות בתחומים כמו חינוך, בריאות וחקר. התוכנית של OpenAI מראה שהחברה רוצה להביא AI גם לשטח הטוב הציבורי, לא רק לעסקים גדולים.",
