    "id": 342,
    "t": "ישור קולקטיבי: דעות ציבור על ה-Model Spec שלנו\n\nOpenAI עשתה סקר בקרב למעלה מ-1,000 אנשים בכל העולם כדי לבחון איך צריך ה-AI להתנהג, והשוו את התוצאות ל-Model Spec שלהם. כל הרעיון הוא שאם אנחנו רוצים AI שמחזיר ערכים אנושיים באמת, אנחנו צריכים להקשיב לדעות של אנשים מכל מקום - ולא רק להניח שאנחנו יודעים מה טוב. התוצאה: AI שיותר משקף את המגוון של דעות וערכים בעולם, במקום להיות כל כך אחד הצדדים.",
