    "id": 343,
    "t": "OpenAI ו-Anthropic חולקות ממצאים מהערכת בטיחות משותפת\n\nבצעד ראשון מסוגו בתעשייה, שתי החברות הגדולות בתחום ה-AI בדקו זו את זו - עם התמקד בבעיות כמו misalignment, hallucinations, jailbreaking וביצוע הוראות. התוצאות מראות הן התקדמות משמעותית והן אתגרים שעדיין מחכים, ובעיקר מדגישות כמה חשובה שיתוף הפעולה בין הלابים השונים על מנת להבטיח שמודלי AI יהיו בטוחים באמת.",
