    "t": "האצת מחקר מדעי החיים\n\nאופנאי והחברה Retro Bio השתמשו ב-GPT-4b micro, מודל AI ספציאליזד, כדי לתכנן חלבונים יעילים יותר למחקר תרפיה בתאים גזעיים וחקר האריכות. זה עוד דוגמה לכך שאלגוריתמים יכולים להאיץ משמעותית גם את המחקר הביומד, לא רק את טכנולוגיה. המודל עזר לחוקרים להגיע לתוצאות שבדרך כלל היו דורשות הרבה יותר זמן וחישוביות. מקור: OpenAI Blog",
