    "t": "GPT-5 ועידן החדש של עבודה\n\nOpenAI הציגה את GPT-5, המודל המתקדם ביותר שלה, שמבטיח להחליף את כללי המשחק בעולם enterprise AI. המודל החדש מסוגל להתאים את עצמו לכל סוג של תהליך עבודה, מאוטומציה של משימות מורכבות ועד שיפור פרודוקטיביות צוותים - וזה אחד מהדברים הגדולים ביותר שתראו בשוק AI השנה.",
