    "t": "GPT-5 למפתחים - הגיע\n\nOpenAI השיקה את GPT-5 בפלטפורמת ה-API שלה, והזה לא בדיחה - מדובר ב-model חדש עם יכולות reasoning מעורערות וביצועים שמנקנקים בכל המשימות קוד בעולם האמיתי. המפתחים יקבלו כלים חדשים וקונטרול טוב יותר על הפלטפורמה, וזה בעצם אומר שחיינו כמפתחים הולכים להשתנות שוב. מקור: OpenAI Blog",
