    "t": "מסירוב קשיח להשלמות בטוחות: כלפי אימון בטיחות ממוקד בפלט\n\nOpenAI חושפת גישה חדשנית ב-GPT-5 שמאזנת בין בטיחות למועילות של התשובות, ובמקום לדחות בחומקות כל בקשה בעייתית, המערכת עכשיו יכולה להבין הקשר ולתת תשובות חכמות יותר. השיטה החדשה של 'safe-completions' מתמודדת עם ה-dual-use prompts (בקשות שיכולות להיות לטובה או לרעה) בדרך אקטיבית יותר, תוך שמירה על סטנדרטים אתיים גבוהים - זה הדיור הבא בהתפתחות AI safety.",
