    "id": 364,
    "t": "הערכת הסיכונים הקיצוניים של מודלים שפה פתוחים\n\nחוקרים מ-OpenAI בחנו את הסיכונים הפוטנציאליים של שחרור מודלים LLM פתוחים, וגילו שאפשר לכוונן אותם באופן זדוני כדי להגביר את היכולות שלהם בתחומים רגישים כמו ביולוגיה וסייבר. המחקר מדגים את החשיבות של הבנת ה-worst-case scenarios לפני פתיחת מודלים חזקים לציבור הרחב, וזה עשוי להיות קריטי לוועדות התקנון העולמיות שעדיין מתחיל בנושא הבטיחות של AI.",
