    "id": 365,
    "t": "GPT-OSS-120B ו-GPT-OSS-20B: מודלים חדשים בקוד פתוח\n\nOpenAI השיקה שני מודלים בקוד פתוח - GPT-OSS-120B ו-GPT-OSS-20B - שמתמחים בפתרון בעיות חישוביות מורכבות, והם זמינים תחת רישיון Apache 2.0. המודלים האלה נועדו לאפשר למפתחים ולמחקרים לעבוד עם מערכות AI חזקות בלי לתלות בשרתי OpenAI, וזה צעד משמעותי בכיוון של דמוקרטיזציה של AI. מדובר בדגמים שמוכלים להתמודד עם משימות reasoning מתחכמות, מה שעשוי לשנות את הכללים בעבור דיפלויים בקנה מידה גדול.",
