    "id": 367,
    "t": "משקלות פתוחים ו-AI לכולם\n\nהקטע הבא בעולם ה-AI לא עוסק רק בעוצמה של המודלים, אלא בשאלה מי בעצם יכול להשתמש בהם. היום OpenAI משחררת את המודלים open-weights שלה החזקים ביותר, צעד ענק שמביא AI מתקדם וגמיש ליותר מקומות בעולם בלי תלות בשירותים קנויניים. זה המהלך שאמור להפוך את הבינה המלאכותית מ-luxury של ענקים לכלי זמין לכל מי שרוצה לעבוד עם זה.",
