    "id": 369,
    "t": "Figma משתמשת ב-AI כדי לחולל מהפכה בעיצוב דיגיטלי\n\nFigma לוקחת צעד גדול קדימה עם כלים חדשים מבוססי AI שמשנים את המשחק לעיצובנים ומפתחים. עם Figma Make, הצוותים יכולים ליצור prototypes, להשתף פעולה וליצור עיצובים בדרך הרבה יותר מהירה וחכמה, אפילו למי שלא בקיא בקוד או עיצוב.",
