    "t": "שלוש שיעורים לבניית יתרון AI קיים\n\nIntercom חשפה איך היא בנתה platform AI שמתרחב בקנה מידה ענק - והדבר קריטי להם היה להשקיע בהערכה נכונה של המודלים, בארכיטקטורה חזקה, וברעיון שצריך לחשוב לטווח ארוך. אם אתם בונים משהו עם AI, יש כאן כמה takeaways שבטוח יעזרו לכם לא ליפול באותם הפחים שבהם כולם נופלים.",
