    "t": "ChatGPT משיקה מצב חדש ללימוד\n\nOpenAI הוציאה לאור את 'Study Mode' החדש ב-ChatGPT - חידוש שמעביר את הצ'אטבוט מעזר פשוט ליוצר חוקר אמיתי. התכונה החדשה מובילה את התלמידים דרך בעיות שלב אחרי שלב, מעירה שאלות חכמות וממסר feedback שמעמיק הבנה - במקום פשוט לתת את התשובה מהקופסה. זה נראה כמו הדחיקה הגדולה של OpenAI להפוך את ChatGPT לכלי ממשי לחינוך.",
