    "t": "Model ML עוזרת לחברות פיננסיות לבנות מחדש מעצמן עם AI\n\nהמוביל בתחום ה-AI המימון, Chaz Englander, מסביר איך infrastructure שנבנה מ-AI ראשוני ו-autonomous agents משנים לחלוטין את דרך עבודתם של חברות פיננסיות. זה לא רק שיפורים כאן ושם - מדובר בהקמת כל המערכת מחדש עם AI בליבה שלה מתחילת הדרך.",
