    "id": 376,
    "t": "OpenAI ו-Penda Health משיקים AI clinical copilot רפואי\n\nOpenAI ו-Penda Health הציגו ממש עכשיו AI copilot חדש לרופאים שמצליח להוריד טעויות אבחון בשיעור של 16% בשימוש ממשי בבתי חולים. זה לא סתם עוד מודל AI - זה פתרון שהוכיח עצמו בשטח ותופס את הדרך הנכונה להחדרת AI בתחום הבריאות בבטחה וביעילות. מדובר בצעד משמעותי שיכול לשנות את דרך עבודתם של הרופאים בימים הקרובים.",
