    "t": "Stargate מתקדם עם שותפות 4.5 GW עם Oracle\n\nOpenAI ו-Oracle חתמו על הסכם לפיתוח 4.5 ג'יגוואט של קיבולת נוספת במרכזי נתונים Stargate בארה״ב, בצעד שיוצר מקומות עבודה חדשים ומחזק את הנהגת ה-AI של ארה״ב. זה לא פחות מאבן דרך גדולה עבור Stargate, פלטפורמת התשתית ל-AI של OpenAI, שמטרתה להנגיש את יתרונות ה-AI לכולם.",
