    "t": "קרן בהיקף 50 מיליון דולר לבניית קהילות\n\nOpenAI הכריזה על קרן ראשונית בסכום של 50 מיליון דולר שמטרתה לתמוך בארגוני ללא-רווח וקהילתיים. הקרן מבוססת על המלצות של ה-OpenAI Nonprofit Commission העצמאית, וכך OpenAI מנסה להדגיש את ההתחייבות שלה לשימוש במי של ה-AI למטרות חברתיות חיוביות.",
