    "t": "הצגת ChatGPT Agent - הסוכן החדש של OpenAI\n\nOpenAI משיקה את ChatGPT Agent, סוכן AI חדש שלא רק משוחח אלא גם חושב ופועל - הוא יכול להשתמש בכלים שונים כדי לבצע משימות כמו מחקר, הזמנות והכנת מצגות, כולם תחת הדרכתך. זה בעצם כמו שיש לך עוזד AI שממש עושה דברים בפועל ולא רק מדבר עליהם.",
