    "t": "כרטיס המערכת של ChatGPT Agent\n\nOpenAI חשפה את הדור החדש של ChatGPT Agent - מודל שמאחד חיפוש אינטרנט, automation של דפדפן וכתיבת קוד בפקד אחד. העניין? כל זה מגיע עם מערכת safeguards שפותחת את הדיון על בטיחות של AI agents חזקים יותר.",
