    "t": "הצהרת דירקטוריון OpenAI בנוגע לדוח הוועדה למטרות חברתיות\n\nדירקטוריון OpenAI הודה לחברי הוועדה הבלתי תלויה למטרות חברתיות על העבודה הנרחבת והמעורדת שלהם. נראה שמדובר בתגובה רשמית לממצאים חשובים שעלולים להשפיע על דרך ההפעלה של החברה וערכיה הלא-רווחיים.",
