    "t": "קריאה לתחרות ממצא באגים בביולוגיה\n\nOpenAI משיקה תחרות חדשה שבה חוקרים יכולים לבדוק את האבטחה של ה-Agent שלהם בـ ChatGPT בעזרת prompt jailbreak אוניברסלי. למי שיצליח למצוא חולשות בה עד $25,000 לתמורה.",
