    "id": 390,
    "t": "סם וג'וני\n\nOpenAI מתכננת משפחה שלמה של מוצרי AI שנועדו להיות נגישים לכולנו. זה לא רק על ChatGPT - מדובר ببניית אקוסיסטם שלם של כלים חכמים שיעבדו יחד כמו משפחה אחת. בעצם, OpenAI רוצה שכל אדם יוכל להשתמש בAI בצורה טבעית וקלה בחייו היומיומיים.",
