    "id": 391,
    "t": "עבודה עם 400,000 מורים לעיצוב עתיד ה-AI בבתי הספר\n\nOpenAI משתפת פעולה עם איגוד המורים האמריקאי בחמש שנות יוזמה ענקית שמטרתה להכשיר 400,000 מחנכים בחטיבות טרום-תיכוניות להנהיג חדשנות AI בכיתות. זה לא רק על שימוש ב-AI בחינוך, אלא על כך שהמורים עצמם יהיו המנהיגים של המהפכה הזו ולא רק צופים מהצד. התוכנית נראית כמו צעד חכם של OpenAI להשפיע על דור חדש של תלמידים שיגדלו עם כלים של AI.",
