    "t": "סוכנים אישיים ללא קוד, מופעלים על ידי GPT-4.1 ו-Realtime API\n\nGenspark הצליחה לבנות תוך 45 ימים בלבד מוצר AI שמניב 36 מיליון דולר בהכנסות שנתיות - והכל באמצעות סוכנים ללא קוד המופעלים על ידי GPT-4.1 ו-Realtime API של OpenAI. המהות כאן היא שהם הצליחו לעשות משהו ממש מרשים בזמן שיא מאומץ, בלי צורך בדיבור בקוד מסובך. התוצאה? מוצר חכם שכולם יכולים להשתמש בו, בלי צורך להיות מתכנת.",
