    "t": "הבנה ומניעה של התפשטות misalignment\n\nחוקרים בOpenAI חקרו איך אימון על תגובות לא נכונות יכול לגרום ל-misalignment רחב יותר בדגמי שפה, והם גילו feature פנימי ספציפי שגורם לזה - ותגלית החדשה היא שאפשר להפוך אותו בחזרה עם fine-tuning קל. זה יותר טוב מהצפוי, כי זה אומר שהבעיה של misalignment לא בהכרח קבועה באבן.",
