    "t": "הרחבת אבטחה דרך גילוי אחראי\n\nOpenAI הכניסה את מדיניות ה-Outbound Coordinated Disclosure שלה, שמסבירה איך החברה מדווחת בצורה אחראית על חולשות באפליקציות של צד שלישי. זה הכל על שמירה על יושרה, עבודה בשיתוף פעולה ואבטחה פרואקטיבית בקנה מידה גדול. בקצרה - OpenAI החליטה להגיד לכולם איך הם עובדים כדי שהקוד של כולנו יהיה בטוח יותר. \n\nמקור: OpenAI Blog",
