    "t": "איך אנחנו מגיבים לדרישות הנתונים של ה-New York Times כדי להגן על פרטיות המשתמשים\n\nOpenAI מתמודדת עם צו בית משפט שדורש שמירת נתוני משתמשי ChatGPT ו-API לנצח, אבל החברה מתעמתת בפחדים על פרטיות המשתמשים שלה. בפוסט רשמי, OpenAI מסבירה איך היא מאזנת בין דרישות משפטיות להגנה על הנתונים שלנו - וזה מעניין כי זה מגע בנושא חם של זכויות יוצרים ופרטיות שנוגע לכל מי שמשתמש ב-AI היום.",
