    "t": "תוספת לכרטיס המערכת של OpenAI o3 ו-o4-mini: OpenAI o3 Operator\n\nOpenAI החליטה להחליף את ה-GPT-4o שהיה בבסיס ה-Operator שלהם בגרסה חדשה שמבוססת על o3, מה שמשמעו שה-Operator יהיה חכם וחזק יותר. ה-API עצמו יישאר עדיין מבוסס על 4o, אבל זה בסדר - העיקר שהעוזר האוטונומי שלהם יהיה ממש מתוחכם. זו עוד הוכחה שOpenAI ממשיכה להעביר את הטכנולוגיה שלהם לדור הבא - הפעם ל-Operator שלהם.",
