    "t": "תוספת ל-o3 וo4-mini: הכירו את Codex\n\nOpenAI שחררה את Codex, סוכן קידוד קלאודי שמופעל על ידי codex-1 - גרסה מיוחדת של o3 המותאמת לפיתוח תוכנה. המערכת תורגלה עם reinforcement learning על משימות קידוד אמיתיות, ויודעת לכתוב קוד שנראה כמו של בני אדם, מכבדת הוראות בדיוק ורצה tests בלופ עד שהכל עובד כשורה.",
