    "t": "הכירו את HealthBench\n\nOpenAI הכניסה לשוק בנצ'מארק חדש שנקרא HealthBench, שנועד להעריך AI מודלים בתחום הבריאות בתרחישים אמיתיים. הבנצ'מארק פותח בשיתוף עם יותר מ-250 רופאים, ומטרתו ליצור סטנדרט משותף להערכת ביצועים וביטחון של מודלים בתחום הרפואה. זו צעד חשוב לשיתוף ידע בקהילת ה-AI healthcare.",
