    "t": "OpenAI מחזקת את הנהיגה עם כניסתה של פידג'י סימו\n\nסאם אלטמן שיתף היום עם הצוות את ההודעה על הצטרפותה של פידג'י סימו להנהלת OpenAI. המהלך הזה מציין שלב חדש בחברה, כשמישהו עם ניסיון רב בהנהלה וטכנולוגיה מצטרף לשורות המנהיגות. זה כל מה שאנחנו יודעים לעת עתה, אבל בטוח שנשמע יותר פרטים בימים הקרובים על התפקידה בדיוק ומה היא תביא לשולחן. מקור: OpenAI Blog",
