    "t": "OpenAI מביאה Data Residency לאסיה\n\nOpenAI מוסיפה אפשרות חדשה שמאפשרת ללקוחות enterprise לשמור את הנתונים שלהם באסיה, כחלק מתוכנית ההגנה על הפרטיות וההתאמה לחוקים שלה. זה אומר שחברות בסין, יפן וסביבה יוכלו להשתמש ב-AI של OpenAI תוך שהם בטוחים שהנתונים שלהם לא עוזבים את האזור.",
