    "t": "לואו'ס שמה את ההיכל בידיים של כל אחד\n\nלואו'ס שיתפה פעולה עם OpenAI בשביל לבנות את MyLow ו-MyLow Companion - כלים מבוססי AI שמביאים עזרה מקצועית הן ללקוחות והן לעובדי החנות. בעצם, הם לקחו את כל הידע של מומחים בשיפוצים וספחו לתוך אפליקציה שיכולה להדריך אתכם בכל שלב של הפרויקט - מתכנון ועד סיום. די משהו, לא?",
