    "t": "AI עוזר ל-John Deere להפוך את החקלאות\n\nג'ון דיר משתמשת ב-AI כדי לעזור לחקלאים לעבוד בצורה חכמה יותר ויעילה. ביותר מדי, החברה מדברת על איך היא מרחיבה את הטכנולוגיה שלה כדי לתמוך בחקלאות בת קיימא ושמירה על הסביבה. זה כבר לא סתם מכונות - זה מערכות חכמות שמבינות את המחקל שלך.",
