    "t": "OpenAI משנה את המבנה שלה\n\nOpenAI הודיעה על שינוי משמעותי בהיררכיה שלה - החברה העסקית תהפוך ל-Public Benefit Corporation תחת פיקוח של הארגון הלא-רווחי. זה בעצם צעד שמטרתו להבטיח שהחברה תמשיך להיות מניעה על ידי מטרה חברתית ולא רק רווחים, וזה קצת כמו קשירת עניבה חוקית להשמירה על הערכים שלה. המהלך הזה מראה שOpenAI רוצה שתהיה לה שליטה ארוכת טווח על כיוון ההתפתחות של ה-AI שלה בדרך הנכונה.",
