    "t": "לואו'ס משתמשת ב-AI כדי לשדרג את חוויית קניות שיפוצים\n\nלואו'ס, שרשרת הקמעונאות הענקית לחומרי בנייה, מטמיעה AI בצורה חכמה בכל ההיבטים של העסק שלה. בשיחה עם כירב הנתונים וה-AI של החברה, נגדל למדוע בזק ודלק של AI יכול לחזות מה הלקוח צריך כשהוא אפילו לא יודע את זה בעצמו.",
