    "t": "BrowseComp: בנצ'מארק חדש לסוכני דפדפן\n\nOpenAI הציגה את BrowseComp, בנצ'מארק חדש שמודד את היכולת של AI agents לנווט באינטרנט ולהשלים משימות מורכבות כמו חיפוש מידע וביצוע פעולות בדפים. הבנצ'מארק הזה אמור לעזור למפתחים לבחון ולשפר את כושר הטיפול שלהם בדפדפן, מה שמוביל לסוכנים חכמים יותר שיכולים לעבוד עבור אנשים בצורה אוטונומית. זה חלק משאיפת OpenAI ליצור AI agents שיוכלו לעזור לנו בעבודה יומיומית במרשתת.",
