    "t": "מימון חדש לבניית דרך לעבר AGI\n\nOpenAI הכריזה על סיבוב מימון ענק של 40 מיליארד דולר שמעלה את הערכת החברה ל-300 מיליארד דולר. הכסף יושקע בהנדסת חקר AI מתקדמת, הרחבת תשתיות החישוב וביצירת כלים חזקים יותר ל-500 מיליון משתמשי ChatGPT שפעילים בשבועות. זה בעצם גם הצעד הבא הגדול בדרך לעבר AGI - בינה כללית מלאכותית.",
