    "id": 445,
    "t": "הצגת יכולת Generate תמונות ב-4o\n\nOpenAI פשוט דחקה את יכולות הGeneration של תמונות ישירות לתוך GPT-4o, ועכשיו תוכלו ליצור תמונות יפות וממש שימושיות ישר מהצ'אט. זה לא רק תמונות נחמדות למראה - זה משהו שאתם בעצם יכולים להשתמש בו ללא מיליון tweaks. OpenAI טוען שחזון זה היה שלהם מתחילת הדרך - שGeneration תמונות צריך להיות חלק ממהות מודלי השפה שלנו. (מקור: OpenAI Blog)",
