    "t": "תוספת לכרטיס המערכת של GPT-4o: יכולות יצירת תמונות חדשות\n\nOpenAI הציגה יכולות חדשות ומרשימות ליצירת תמונות ב-GPT-4o שמובילות בשנילים את DALL·E 3 הקודם - המודל החדש יכול ליצור תמונות בתצילום ריאליסטי וגם להשתמש בתמונות קיימות כ-input להנדסתן שינוי. זו קפיצה משמעותית בתחום ה-generative AI שמצביעה על המשך התפתחות מהר של כלים אלו בידי הטכנולוגיה הגדולה. מקור: OpenAI Blog",
