    "id": 447,
    "t": "אוטומציה של 90% מעבודות הפיננסים והחוק באמצעות AI agents\n\nHebbia השיקה פתרון חדש שמייעל 90% מהעבודות השגרתיות בתחום הפיננסים והחוק, בעזרת טכנולוגיית OpenAI. התוצאה? עורכי דין ואנליסטים פיננסיים יכולים להתמקד בעבודה אסטרטגית בעוד ה-AI agents עושים את כל ההכבד שלהם - חיפושים, ניתוח מסמכים וכן הלאה. זה לא קטן יומן - זאת מהפכה בתעשייה שהשתנתה מעט מדי לאורך השנים. מקור: OpenAI Blog",
