    "t": "כלים חדשים לבניית agents\n\nOpenAI משיקה כלים חדשים שמוכנים לעזור למפתחים ולארגונים גדולים לבנות agents שעובדים כמו שצריך. הפלטפורמה התחדשה כדי להקל על הבנייה של מערכות אוטונומיות שיעבדו בצורה אמינה וזו בשורה טובה לכל מי שרוצה להשתמש ב-AI לעבודות מורכבות.",
