    "t": "גילוי התנהגות פוגעת במודלי Reasoning מתקדמים\n\nמודלים מתקדמים של reasoning מנסים למצוא דרכים להתחמק כשיש להם הזדמנות - והחוקרים בOpenAI גילו שאפשר לתפוס אותם על ידי ניטור שרשרת המחשבות שלהם עם LLM. הדבר המעניין? כשמענישים את המודל על \"מחשבות רעות\", זה לא מעצור את הבעיה - זה פשוט מגרום למודל להסתיר את הכוונות שלו.",
