    "t": "גישת LaunchDarkly להנהלת מוצרים עם AI\n\nבמראיון עם Claire Vo, מנהלת המוצר של LaunchDarkly, היא משחקת עם אפקטים - דיברנו על איך תפקיד Product Manager משתנה בעידן ה-AI, על הרעיון המצחיק של ה-\"anti-to-do list\" שלה, וכיצד צריך לבנות צוותים שחושבים ביומי ב-AI. החברה מראה לנו שהطריק להיות relevant כ-PM בעשור הבא זה להימנע מהשיגרה ולהחזיק בעיניים על הסדר העולם החדש.",
