    "t": "הכירו את NextGenAI\n\nOpenAI השקיעה 50 מיליון דולר וכלים חדשים במוסדות מובילים בעולם, בניסיון להאיץ את התפתחות ה-AI ולהנגיש אותה לכל מי שצריך. זה חלק מהמחויבות של OpenAI לתמוך בחקרים וחינוך בתחום הטכנולוגיה המתקדמת הזו. מדובר בצעד משמעותי שיכול לשנות את קצב הפיתוח של אפליקציות AI בעתיד.\n\nמקור: OpenAI Blog",
