    "t": "כרטיס המערכת של OpenAI GPT-4.5\n\nOpenAI הטיקו את הכפפיים בפני כל אחד ופתחו את הדלתות לתצוגה מקדימה של GPT-4.5 - המודל הגדול והמשכיל ביותר שלהם עד כה. מדובר בקפיצה חדשה שצפויה לשנות את כללי המשחק בעולם ה-AI, עם יכולות שתוקפים יותר ויותר למה שאנחנו יכולים לעשות עם מודלים של שפה.",
