    "t": "נלחמים בשימוש זדוני ב-AI\n\nOpenAI משחקת תפקיד פעיל בהבטחת שהטכנולוגיה של AI תשמש את הטובה - דרך פיתוח AI דמוקרטי, מניעת ניסיונות לניצול לרעה, והגנה מפני איומים אוטוריטריים שעלולים להשתמש בה כנשק למדכא חופש. זה לא רק סיפור טכני, זה שאלה יסודית של מי שולט בעוד שהטכנולוגיה הזו הולכת ומשנה את העולם.",
