    "t": "אובר משתמשת ב-AI כדי להביא חוויות מיוחדות לדרישה\n\nאובר משתמשת בכוח ה-AI כדי להפוך את כל טריפ וצו מזון למשהו באמת מיוחד ומותאם לכל משתמש - וזה לא בדיוק טיוטה רנדומלית. בראיון עם ראש ה-AI של אובר, מתברר איך הייטק הזה עוזר לחברה ללמוד מהעדפות שלנו ולהנבא בדיוק מה אנחנו צריכים, לפני שאפילו נדע שצריכים. זהו הדיבור על מכונות שלא סתם מסתובבות בכביש - הן חושבות איתנו.",
