    "t": "SWE-Lancer: בנצ'מרק חדש לבדיקת יכולות ה-LLM\n\nOpenAI בדקה אם מודלים מהדור החדש של בינה מלאכותית יכולים להרוויח מיליון דולר מעבודות real-world בפיתוח תוכנה בפלטפורמות freelance. התוצאות מגילות כמה רחוק עדיין AI מלהחליף software engineers אמיתיים, אבל גם מראות את הפוטנציאל המדהים של הדור הבא של מודלים. זה לא רק שאלה כמה AI יכול להרוויח - זה בדיקה חיקאית חדשה להבנת היכולות האמיתיות של frontier LLMs. | מקור: OpenAI Blog",
