    "id": 494,
    "t": "סוכן בעל יכולת שימוש במחשב\n\nOpenAI משיקה ממשק אוניברסלי שמאפשר ל-AI לתקשר עם העולם הדיגיטלי כמו אדם - הוא יכול ללחוץ כפתורים, להקליד טקסט וללמוד מה שהוא רואה על המסך. זו תרומה גדולה שיכולה לשנות את אופן שבו אנחנו עובדים עם תוכנות וממשקים דיגיטליים. מחשבה על עתיד שבו AI יכול להשמש כעוזר אוטומטי לכמעט כל משימה במחשב שלך. מקור: OpenAI Blog",
