    "t": "כרטיס מערכת Operator\n\nOpenAI חשפה היום את גישתה השלתונית לאבטחת ה-AI של מערכת Operator החדשה שלהם. הדוקומנט מפרט את השכבות ההגנה המרובות שהם בנו - מפחתות על prompt engineering וjailbreaks, דרך הגנות פרטיות וביטחוניות, ועד לעבודות red teaming חיצוניות שהם מנהלים עם חוקרים בחוץ. בקיצור, זה כל ההסברים שלהם למה המערכת הזאת יותר בטוחה מאשר מה שהיה לפני.",
